const body = $input.first().json.body || $input.first().json;
const event = body.event || 'system.update';
const timestamp = body.timestamp || new Date().toISOString();
const data = body.data || body;

const emojiByModule = {
  'Tareas': '✅',
  'Notas y Wiki': '📝',
  'Proyectos': '🚀',
  'CRM — Clientes': '🎉',
  'CRM — Leads': '🎯',
  'CRM — Entrevistas': '🎙️',
  'Contactos': '📇',
  'Contabilidad': '💶',
  'Progreso — OKRs': '📈',
  'Progreso — Hitos': '🏆',
  'Cerebro Omega — Prompts': '🧠'
};

let whatsappMessage = '';

if (event === 'client.closed' && data.client) {
  const c = data.client;
  whatsappMessage = [
    `🎉 *¡NUEVO CLIENTE CERRADO EN OMEGA OS!*`,
    ``,
    `🏢 *Empresa:* ${c.companyName} (${c.cif})`,
    `👥 *Empleados:* ${c.employees}`,
    `💶 *Cuota MRR:* ${c.monthlyQuotaEur} €/mes`,
    `🛠️ *Setup inicial:* ${c.setupFeeEur} €`,
    `👤 *Cerrado por:* ${data.closedBy || 'Socio'}`,
    `🕒 _${timestamp}_`
  ].join('\n');
} else if (event === 'margin.alert') {
  whatsappMessage = [
    `⚠️ *ALERTA DE MARGEN BRUTO (<80%)*`,
    ``,
    `📉 *Margen actual:* ${data.grossMarginPercent}%`,
    `💶 *MRR:* ${data.mrr} € | *Únicos:* ${data.oneOff} €`,
    `💸 *Gastos variables:* ${data.variableExpenses} €`,
    `🕒 _${timestamp}_`
  ].join('\n');
} else if (event === 'task.urgent' && data.task) {
  const t = data.task;
  whatsappMessage = [
    `🚨 *NUEVA TAREA URGENTE — OMEGA OS*`,
    ``,
    `📌 *Título:* ${t.title}`,
    `👤 *Asignada a:* ${data.assignee}`,
    `📅 *Fecha límite:* ${t.dueDate || 'Sin fecha'}`,
    `🕒 _${timestamp}_`
  ].join('\n');
} else {
  const moduleName = data.module || 'Omega OS';
  const icon = emojiByModule[moduleName] || '🔔';
  const actor = data.actor || 'Omega OS';
  const summary = data.summary || `Evento: ${event}`;
  const details = data.details ? `\nℹ️ _${data.details}_` : '';

  whatsappMessage = [
    `${icon} *Omega OS — ${moduleName}*`,
    `👤 *Por:* ${actor}`,
    `📌 *${summary}*${details}`,
    `🕒 _${timestamp}_`
  ].join('\n');
}

return [
  {
    json: {
      event,
      module: data.module || 'Omega OS',
      actor: data.actor || 'Omega OS',
      whatsappMessage,
      raw: body
    }
  }
];
